ALTER TABLE articles ADD COLUMN publisher_notice TEXT CHECK(publisher_notice IS NULL OR length(publisher_notice) <= 5000);
CREATE TABLE dataset_notices (id TEXT PRIMARY KEY, document TEXT NOT NULL CHECK(length(document) <= 50000));
INSERT INTO dataset_notices (id,document) VALUES ('publisher','{"version":1,"reviewedAt":"2026-11-25","scope":"GapSound is configured for private, local reading. These notices identify sources and grant no additional rights; the individual license terms still apply.","items":[{"id":"cve","name":"CVE Program","attribution":"Copyright © 1999-2026, The MITRE Corporation. CVE is a trademark and the CVE logo is a registered trademark of The MITRE Corporation.","termsUrl":"https://www.cve.org/Legal/TermsOfUse","text":"License\n\nSubmissions: For all materials you submit to the Common Vulnerabilities and Exposures (CVE™), you hereby grant to The MITRE Corporation (MITRE) and all CVE Numbering Authorities (CNAs) a perpetual, worldwide, non-exclusive, no-charge, royalty-free, irrevocable copyright license to reproduce, prepare derivative works of, publicly display, publicly perform, sublicense, and distribute such materials and derivative works. Unless required by applicable law or agreed to in writing, you provide such materials on an \"AS IS\" BASIS, WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied, including, without limitation, any warranties or conditions of TITLE, NON-INFRINGEMENT, MERCHANTABILITY, or FITNESS FOR A PARTICULAR PURPOSE.\n\nCVE Usage: MITRE hereby grants you a perpetual, worldwide, non-exclusive, no-charge, royalty-free, irrevocable copyright license to reproduce, prepare derivative works of, publicly display, publicly perform, sublicense, and distribute Common Vulnerabilities and Exposures (CVE™). Any copy you make for such purposes is authorized provided that you reproduce MITRE''s copyright designation and this license in any such copy.\n\nDisclaimers\n\nALL DOCUMENTS AND THE INFORMATION CONTAINED THEREIN PROVIDED BY MITRE ARE PROVIDED ON AN \"AS IS\" BASIS AND THE CONTRIBUTOR, THE ORGANIZATION HE/SHE REPRESENTS OR IS SPONSORED BY (IF ANY), THE MITRE CORPORATION, ITS BOARD OF TRUSTEES, OFFICERS, AGENTS, AND EMPLOYEES, DISCLAIM AL